/**
 * Pagination Helper — Cursor/offset pagination for API responses.
 * Generated by BackendForge
 */

/**
 * Parse pagination params from query string.
 */
const parsePagination = (query) => {
  const page = Math.max(1, parseInt(query.page) || 1);
  const limit = Math.min(100, Math.max(1, parseInt(query.limit) || 20));
  const offset = (page - 1) * limit;
  const sort = query.sort || 'createdAt';
  const order = (query.order || 'desc').toUpperCase();
  return { page, limit, offset, sort, order };
};

/**
 * Build a paginated response.
 */
const paginatedResponse = (data, total, pagination) => {
  const { page, limit } = pagination;
  const totalPages = Math.ceil(total / limit);
  return {
    data,
    pagination: {
      page,
      limit,
      total,
      totalPages,
      hasNext: page < totalPages,
      hasPrev: page > 1,
    },
  };
};

/**
 * Build Sequelize findAndCountAll options with pagination.
 */
const sequelizePagination = (pagination, extraOptions = {}) => {
  const { offset, limit, sort, order } = pagination;
  return {
    offset,
    limit,
    order: [[sort, order]],
    ...extraOptions,
  };
};

module.exports = {
  parsePagination,
  paginatedResponse,
  sequelizePagination,
};
